<script>
import PhotoCard from './PhotoCard.svelte'; import Icon from './Icon.svelte';
let {station:s,index:i,data,selected,learned,parentMode,printing=false}=$props();
let layer=$state(0),night=$state(false);
const descriptions=['封土：地面上的土堆和墓坑填土，把墓葬深埋在地下。','白膏泥：一种黏性较强、透水性较低的土，用来填塞封护。','木炭：棺椁周围的封护材料之一。保存条件是深埋、密封与环境等多种因素共同作用的结果。','木椁（guǒ）：棺外较大的木结构，旁边的边厢可放随葬物品。','棺（guān）：用来安放逝者的葬具，位于椁的内部。'];
const boxes=[[8,8,324,194,15,'#d4c4a2'],[31,30,278,150,9,'#f6edcf'],[55,52,230,106,5,'#6d7368'],[84,75,172,61,2,'#c28e59'],[124,90,92,31,4,'#725036']];
</script>
<article id={'station-'+s.id} class="station" hidden={selected!==s.id} aria-labelledby={'title-'+s.id}>
<header class="station-heading"><div class="tag-line"><span class="eyebrow">讲解卡 {String(i+1).padStart(2,'0')}</span><span class="pill" class:orange={s.optional}>{s.area}{s.optional?' · 预约成功后备选':''}</span></div><h3 id={'title-'+s.id}>{s.name}</h3><p>{s.subtitle}</p><div class="location-line"><Icon name="pin"/><span>{s.location}</span></div></header>
{#if s.photoIds?.length}<section class="photo-section" aria-label={(s.navTitle||s.name)+'的真实图像'}><div class="photo-intro"><h4>看图讲故事</h4><span>照片按需加载 · 离线保存后可完整查看</span></div><div class="photo-grid">{#each s.photoIds as id}{@const p=data.photos.find(p=>p.id===id)}{#if p}<PhotoCard photo={p} enabled={selected===s.id||printing}/>{/if}{/each}</div>{#if s.photoNote}<p class="photo-section-note">{s.photoNote}</p>{/if}</section>{/if}
<div class="story-top"><div class="story-title"><Icon name="book"/>直接读给孩子听 · 约2分钟</div><button class="listen-btn" data-speak={s.id} aria-pressed="false"><Icon name="sound"/>听一遍</button></div><div class="story">{#each s.story as p}<p>{p}</p>{/each}</div><div class="takeaway"><strong>记住这一句：</strong>{s.takeaway}</div>
{#if s.interactive==='seal'}<div class="seal"><div class="seal-top"><strong>动手看一看：一层层怎样保护？</strong><span class="muted small">结构示意，非考古比例</span></div><div class="seal-view"><svg class="seal-diagram" viewBox="0 0 340 210" role="img" aria-label="由外到内的墓葬封护结构示意">{#each boxes as box,j}<rect class="seal-rect" class:active={layer===j} data-layer-shape={j} x={box[0]} y={box[1]} width={box[2]} height={box[3]} rx={box[4]} fill={box[5]} stroke="#515b50"/>{/each}<text x="170" y="111" text-anchor="middle" fill="#fff8e8" font-size="15">棺</text></svg><div class="seal-controls">{#each ['封土','白膏泥','木炭','木椁','棺'] as name,j}<button class:active={layer===j} data-layer={j} aria-pressed={layer===j} onclick={()=>layer=j}>{j+1} {name}</button>{/each}</div></div><p class="seal-explain" aria-live="polite">{descriptions[layer]}</p></div>{:else if s.interactive==='lake'}<div class="lake-demo" class:night><div class="lake-moon"></div><div class="lake-island"></div><div class="lake-shine"></div><div class="lake-caption"><span>意境示意：白天看湖，也能想象诗中月夜。</span><button class="lake-toggle" aria-pressed={night} onclick={()=>night=!night}>{night?'切回白天看湖 ☀':'切到诗中月夜 ☾'}</button></div></div>{/if}
<div class="micro-title"><Icon name="compass"/>现场找这几条线索</div><ol class="facts-list">{#each s.facts as f,j}<li><span class="fact-number">{j+1}</span><div class="fact-body"><strong>{f.title}</strong><p>{f.text}</p></div></li>{/each}</ol>
{#if s.boundary}<aside class="boundary"><strong>{s.boundary.title||'讲给孩子时，分清这一点'}</strong><p>{s.boundary.text||s.boundary}</p></aside>{/if}
{#if s.people?.length}<div class="micro-title"><Icon name="star"/>这站认识谁</div><div class="people-tags">{#each s.people as id}{@const p=data.people.find(p=>p.id===id)}{#if p}<a class="person-tag" href={'#person-'+p.id}><b>{p.name}</b> · {p.shortRole}</a>{/if}{/each}</div>{/if}
{#if s.poems?.length}<div class="micro-title"><Icon name="book"/>在这里读一读</div>{#each s.poems as id}{@const p=data.poems.find(p=>p.id===id)}{#if p}<div class="related-poem"><h4>《{p.title}》 · {p.author}</h4><p>{#each p.lines.slice(0,p.excerptCount||2) as line}{line}<br>{/each}</p><small>{p.stationNote||p.context}</small><br><a class="text-link small" href={'#poem-'+p.id}>打开完整诗文与儿童译意 ↗</a></div>{/if}{/each}{/if}
<div class="micro-title"><Icon name="leaf"/>亲子小任务</div>{#each s.subStops||[] as sub}<details class="substop"><summary>{sub.name}</summary><div class="detail-content"><p>{sub.text}</p></div></details>{/each}<div class="tasks"><ul>{#each s.tasks as task}<li>{task}</li>{/each}</ul></div>
<details class="parent-details" open={parentMode}><summary>家长备课：历史时间线与讲解提示</summary><div class="detail-content">{#if s.timeline?.length}<ul class="history-timeline">{#each s.timeline as t}<li><b>{t.when}</b><span>{t.text}</span></li>{/each}</ul>{/if}{#each s.parentNotes||[] as p}<p>{p}</p>{/each}</div></details>
<details class="source-details"><summary>这张讲解卡的资料来源（{s.sources.length}）</summary><div class="detail-content source-links">{#each s.sources as source}<div><a href={source.url} target="_blank" rel="noopener noreferrer">↗ {source.title}</a>{#if source.supports}<p>{source.supports}</p>{/if}</div>{/each}</div></details>
<footer class="station-footer"><button class="stamp-btn" class:stamped={learned.includes(s.id)} data-stamp={s.id}><Icon name="check"/><span>{learned.includes(s.id)?'这站已盖章':'这站学会啦，盖个章'}</span></button><div class="station-steps"><button data-step="-1" data-from={s.id} aria-label="上一站">←</button><button data-step="1" data-from={s.id} aria-label="下一站">→</button></div></footer>
</article>
